<div class="page-heading admin-heading admissions-index-heading"><div><span class="eyebrow">Admissions module</span><h1>Admission management</h1><p>Configure, validate, publish and monitor every admission cycle from one database-driven workspace.</p></div><div class="heading-actions"><?php if(can('admissions.manage')):?><a class="button button-primary" href="<?= url('admin/admissions/create') ?>">+ Create cycle</a><?php endif?></div></div>
<div class="admin-stat-grid"><article><div class="stat-icon teal">◎</div><div><span>Admission cycles</span><b><?= number_format($stats['cycles']) ?></b><small>All configured cycles</small></div></article><article><div class="stat-icon green">●</div><div><span>Live now</span><b><?= number_format($stats['live']) ?></b><small>Server-calculated status</small></div></article><article><div class="stat-icon gold">▤</div><div><span>Applications</span><b><?= number_format($stats['applications']) ?></b><small>Across all cycles</small></div></article><article><div class="stat-icon red">⌛</div><div><span>Action queue</span><b><?= number_format($stats['pending']) ?></b><small>Review or applicant action</small></div></article></div>
<section class="card application-table-card admission-cycle-table-card"><div class="card-heading"><div><span class="eyebrow">Source of truth</span><h2>Admission cycles</h2></div></div><?php if(!$cycles):?><div class="empty-state"><span>◎</span><h2>No admission cycle configured</h2><p>Create a draft, then add programmes, eligibility, seats, forms, documents and fees before publishing.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Cycle</th><th>Effective status</th><th>Programmes / seats</th><th>Applications</th><th>Readiness</th><th>Window</th><th></th></tr></thead><tbody><?php foreach($cycles as $cycle):?><tr><td><b><?= e($cycle['name']) ?></b><small class="cell-subtitle"><?= e($cycle['code']) ?> · <?= e($cycle['session_name']) ?></small></td><td><span class="status-pill status-<?= e($cycle['effective_status']) ?>"><?= e(ucwords(str_replace('_',' ',$cycle['effective_status']))) ?></span><small class="cell-subtitle">Stored: <?= e($cycle['status']) ?></small></td><td><b><?= number_format((int)$cycle['program_count']) ?></b> / <?= number_format((int)$cycle['capacity']) ?></td><td><b><?= number_format((int)$cycle['application_count']) ?></b><small class="cell-subtitle"><?= number_format((int)$cycle['admitted_count']) ?> admitted</small></td><td><?php if($cycle['readiness']['ready']):?><span class="status-pill status-verified">Ready</span><?php else:?><span class="status-pill status-rejected"><?= count($cycle['readiness']['errors']) ?> issue<?= count($cycle['readiness']['errors'])===1?'':'s' ?></span><?php endif?></td><td><?= format_date($cycle['starts_at']) ?><small class="cell-subtitle">to <?= format_date($cycle['ends_at']) ?></small></td><td><a class="row-action" href="<?= url('admin/admissions/'.$cycle['id']) ?>">→</a></td></tr><?php endforeach?></tbody></table></div><?php endif?></section>
<section class="card application-table-card programme-catalogue-card"><div class="card-heading"><div><span class="eyebrow">Reusable catalogue</span><h2>Programmes and courses</h2></div><span><?= count($programs) ?> records</span></div><div class="table-wrap"><table><thead><tr><th>Programme</th><th>Code</th><th>Award</th><th>Duration</th><th>Cycle use</th><th>Status</th></tr></thead><tbody><?php foreach($programs as $program):?><tr><td><b><?= e($program['name']) ?></b><small class="cell-subtitle"><?= e($program['department_name']?:'College-wide') ?></small></td><td><code><?= e($program['code']) ?></code></td><td><?= e($program['award_type']) ?></td><td><?= e($program['duration_years']) ?> years · <?= e($program['total_semesters']) ?> semesters</td><td><?= number_format((int)$program['cycle_count']) ?> cycle(s)</td><td><span class="status-pill status-<?= e($program['status']) ?>"><?= e(ucfirst($program['status'])) ?></span></td></tr><?php endforeach?></tbody></table></div><?php if(can('admissions.manage')):?><details class="settings-inline-form admission-programme-create"><summary class="button button-outline">+ Add programme to catalogue</summary><form method="post" action="<?= url('admin/admissions/programs') ?>"><?= csrf_field() ?><div class="form-grid three"><label><span>Name</span><input name="name" required></label><label><span>Code</span><input name="code" required placeholder="BPHARM"></label><label><span>Award type</span><input name="award_type" value="Undergraduate Degree"></label><label><span>Duration (years)</span><input type="number" min=".5" step=".5" name="duration_years" value="4"></label><label><span>Total semesters</span><input type="number" min="1" name="total_semesters" value="8"></label><label class="full"><span>Public summary</span><textarea name="summary"></textarea></label></div><button class="button button-primary">Create programme</button></form></details><?php endif?></section>
